definition.script:
import groovy.json.JsonSlurper;
def infrastructure_git_hash
pipeline { agent any
options { skipDefaultCheckout(true) }
stages { stage('Clean Workspace') { steps { deleteDir() } }
stage('Download Template') { steps { script { def templates = [ 'Gateway': ['gateway.env.tftpl', 'configs/gateway/templates'], 'Operations': ['operations.env.tftpl', 'configs/operations/templates'], 'Query': ['query.env.tftpl', 'configs/query/templates'], 'HPDS Auth': ['hpds-auth.env.tftpl', 'configs/hpds/templates'], 'HPDS Open': ['hpds-open.env.tftpl', 'configs/hpds/templates'], 'Visualization': ['visualization.env.tftpl', 'configs/pic-sure-visualization/templates'] ]
def selected = templates[params.SERVICE] if (selected == null) { error("Unsupported SERVICE selection: ${params.SERVICE}") }
env.TEMPLATE_FILE = selected[0] env.TEMPLATE_PREFIX = selected[1]
def s3Status = sh(script: '''#!/bin/bash set -euo pipefail
source_scripts_folder="${JENKINS_HOME}/workspace/Bash_Functions/" shopt -s nullglob for script_file in "$source_scripts_folder"*.sh; do chmod +x "$script_file" if [[ -f "$script_file" && -x "$script_file" ]]; then source "$script_file" fi done shopt -u nullglob
for fn in assume_role reset_role; do if ! command -v "$fn" >/dev/null 2>&1; then echo "Error: required function '$fn' was not loaded from $source_scripts_folder." >&2 exit 1 fi done
: "${stack_s3_bucket:?stack_s3_bucket is required}" : "${TEMPLATE_FILE:?TEMPLATE_FILE is required}" : "${TEMPLATE_PREFIX:?TEMPLATE_PREFIX is required}"
template_file="$TEMPLATE_FILE" template_prefix="$TEMPLATE_PREFIX"
role_assumed=false cleanup() { if [[ "$role_assumed" == true ]]; then reset_role fi } trap cleanup EXIT
assume_role role_assumed=true
download_s3_template() { local object_key=$1 local destination=$2 local aws_error local candidate
if ! candidate=$(mktemp "$(dirname "$destination")/.template-download.XXXXXX"); then echo "Error: could not create a temporary template file." >&2 return 2 fi
if aws_error=$(aws s3 --sse=AES256 cp "s3://$stack_s3_bucket/$object_key" "$candidate" 2>&1 >/dev/null); then if [[ ! -s "$candidate" ]]; then rm -f "$candidate" echo "Error: s3://$stack_s3_bucket/$object_key is empty; refusing to use it." >&2 return 2 fi if ! mv "$candidate" "$destination" >/dev/null 2>&1; then rm -f "$candidate" echo "Error: could not promote downloaded template to $destination." >&2 return 2 fi return 0 fi
rm -f "$candidate"
case "$aws_error" in *"An error occurred (404)"*|*"An error occurred (NoSuchKey)"*|*"An error occurred (NotFound)"*) return 1 ;; esac
echo "Error: could not read s3://$stack_s3_bucket/$object_key; refusing to fall back after a non-missing-object AWS error." >&2 return 2 }
if download_s3_template "$template_prefix/$template_file" "$template_file"; then echo "Using shared S3 template for $template_file" exit 0 else download_status=$? if [[ $download_status -ne 1 ]]; then exit "$download_status" fi fi
echo "No S3 template found, using repo version of $template_file" exit 3 ''', returnStatus: true)
if (s3Status == 3) { if (params.INFRASTRUCTURE_GIT_HASH?.trim()) { infrastructure_git_hash = params.INFRASTRUCTURE_GIT_HASH.trim() echo "Using provided INFRASTRUCTURE_GIT_HASH: ${infrastructure_git_hash}" } else { def result = build job: 'Retrieve Build Spec' copyArtifacts filter: 'build-spec.json', projectName: 'Retrieve Build Spec', selector: specific("" + result.number) def buildSpec = new JsonSlurper().parse(new File("${env.WORKSPACE}/build-spec.json")) infrastructure_git_hash = buildSpec.infrastructure_git_hash echo "Resolved INFRASTRUCTURE_GIT_HASH from release control: ${infrastructure_git_hash}" }
checkout([ $class: 'GitSCM', userRemoteConfigs: [[ url: "${infrastructure_git_repo}", credentialsId: "${git_credentials_id}" ]], branches: [[name: infrastructure_git_hash]], extensions: [[$class: 'RelativeTargetDirectory', relativeTargetDir: 'infra']] ])
sh '''#!/bin/bash set -euo pipefail
: "${TEMPLATE_FILE:?TEMPLATE_FILE is required}"
repo_template="infra/app-infrastructure/template-renderer/templates/$TEMPLATE_FILE" if [[ ! -s "$repo_template" ]]; then echo "Error: repository fallback $TEMPLATE_FILE is missing or empty." >&2 exit 1 fi cp "$repo_template" "$TEMPLATE_FILE" ''' } else if (s3Status != 0) { error("Template download failed before repository fallback (exit ${s3Status}).") } } } } }
post { success { archiveArtifacts artifacts: '*.env.tftpl', allowEmptyArchive: false } } }
